@call_base_class_method_with_same_name
class CloudBts(NokiaProxyPc):
    r"""
    CloudBts device class.

    Example of device in yaml configuration file:
      - with PROXY_PC:
      GNB0_OAM:
        DEVICE_CLASS: ta_moler.device.cloud_bts.CloudBts
        CONNECTION_HOPS:
          PROXY_PC:
            SERVICE_USER:
              command_params:
                host: host_ip
            OAM:
              command_params:
                host: host_ip
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: proxy_pc_prompt
                host: host_ip
                login: login
                password: password
          OAM:
            PROXY_PC:
              command_params:
                expected_prompt: proxy_pc_prompt
          SERVICE_USER:
            PROXY_PC:
              command_params:
                expected_prompt: proxy_pc_prompt
      GNB0_CPCL:
        DEVICE_CLASS: ta_moler.device.cloud_bts.CloudBts
        INITIAL_STATE: CPCL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            PROXY_PC:
              execute_command: ssh
              command_params:
                expected_prompt: proxy_pc_prompt
                host: host_ip
                login: login
                password: password
          PROXY_PC:
            SERVICE_USER:
              command_params:
                host: host_ip
            OAM:
              command_params:
                host: host_ip
          OAM:
            PROXY_PC:
              command_params:
                expected_prompt: proxy_pc_prompt
          SERVICE_USER:
            PROXY_PC:
              command_params:
                expected_prompt: proxy_pc_prompt
      -without PROXY_PC:
      GNB0_OAM:
        DEVICE_CLASS: ta_moler.device.cloud_bts.CloudBts
        CONNECTION_HOPS:
          UNIX_LOCAL:
            OAM:
              execute_command: ssh
              command_params:
                host: host_ip
      GNB0_CPCL:
        DEVICE_CLASS: ta_moler.device.cloud_bts.CloudBts
        INITIAL_STATE: CPCL
        CONNECTION_HOPS:
          UNIX_LOCAL:
            OAM:
              execute_command: ssh
              command_params:
                host: host_ip
            SERVICE_USER:
              execute_command: ssh
              command_params:
                host: host_ip
    """

    oam = "OAM"
    cpcl = "CPCL"
    cpif = "CPIF"
    cpnb = "CPNB"
    cpue = "CPUE"
    upue = "UPUE"
    cpnrt = "CPNRT"
    db = "DB"
    service_user = "SERVICE_USER"
    fct = "FCT"
    du = "DU"
    fsclish = "FSCLISH"

    _re_oam_prompt = r'\[(?!(root|serviceuser)@.*$)\w+@\S+oam\S+\]'  # [robot@5gbts-307-oam-000:/home/robot] $
    _re_cpcl_prompt = r'\[\w+@\S+cpcl\S+\]'
    _re_cpif_prompt = r'\[\w+@\S+cpif\S+\]'
    _re_cpnb_prompt = r'\[\w+@\S+cpnb\S+\]'
    _re_cpue_prompt = r'\[\w+@\S+cpue\S+\]'
    _re_upue_prompt = r'\[\w+@\S+upue\S+\]'
    _re_cpnrt_prompt = r'\[\w+@\S+cpnrt\S+\]'
    _re_db_prompt = r'\[\w+@\S+db\S+\]'
    _re_du_prompt = r'root@fct-0a:.*>'
    _re_fsclish_prompt = r'root@\S+oam(\S+)\s+\[\S+\]'  # root@5gbts-393-oam-000 [5gbts-393]
    _re_fct_prompt = r'\[root@\S+oam\S+\]'  # [root@5gbts-307-oam-000:/home/robot] #
    _re_service_user_prompt = r'serviceuser@.+>'  # serviceuser@5gbts-190-oam-000 [5gbts-190]  >
    _exit_to_oam = {oam: {  # to
        "execute_command": "exit",  # using command
        "command_params": {  # with parameters
            "expected_prompt": f"{_re_oam_prompt}\\s+\\$",
        },
        "required_command_params": []
    }, }

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create Unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else CloudBts.oam
        super(CloudBts, self).__init__(sm_params=sm_params, name=name, io_connection=io_connection, io_type=io_type,
                                       variant=variant, io_constructor_kwargs=io_constructor_kwargs,
                                       initial_state=initial_state, lazy_cmds_events=lazy_cmds_events)
        self.logger = logging.getLogger('moler.cloud_bts')

    def _get_forbidden_states_no_proxy_pc(self) -> dict:
        """
        Get forbidden states when deleted states - no proxy pc.

        :return: forbidden states.
        """
        forbidden = {
            self.oam: self.service_user,
            self.service_user: self.oam,

            self.cpcl: self.oam,
            self.cpif: self.oam,
            self.cpnb: self.oam,
            self.cpue: self.oam,
            self.upue: self.oam,
            self.cpnrt: self.oam,
            self.db: self.oam,
            self.fct: self.oam,
            self.du: self.oam,
            self.fsclish: self.oam,

        }
        return forbidden
        return None

    def _get_additional_state_hops_no_proxy_pc(self) -> dict:
        """
        Get additional state hops if states are removed. None if no additional states are required.

        :return: additional states.
        """
        additional_hops = {
            self.service_user: {
                self.cpcl: self.unix_local,
                self.cpif: self.unix_local,
                self.cpnb: self.unix_local,
                self.cpnrt: self.unix_local,
                self.cpue: self.unix_local,
                self.db: self.unix_local,
                self.du: self.unix_local,
                self.fct: self.unix_local,
                self.fsclish: self.unix_local,
                self.oam: self.unix_local,
                self.upue: self.unix_local,
            },
            self.oam: {
                self.service_user: self.unix_local
            },
        }
        return additional_hops

    def _get_forbidden_hops_no_proxy_pc(self):
        forbidden_hops = {
            self.service_user: {
                self.cpcl: self.oam,
                self.cpif: self.oam,
                self.cpnb: self.oam,
                self.cpnrt: self.oam,
                self.cpue: self.oam,
                self.db: self.oam,
                self.du: self.oam,
                self.fct: self.oam,
                self.fsclish: self.oam,
                self.upue: self.oam,
            },
        }
        return forbidden_hops

    def change_du_address(self, du_address):
        """
        Change DU address for state machine.

        :param du_address: address of DU to set.
        :return: None
        """
        self._configurations[CloudBts.connection_hops][CloudBts.cpif][CloudBts.du]['command_params']['host'] = \
            du_address

